INSERT INTO legion_teeming_guard SELECT COUNT(*)=0 FROM waypoint_data a LEFT JOIN legion_teeming_expected_waypoint_data e ON a.id=e.id AND a.point=e.point WHERE a.id BETWEEN 1467062000 AND 1467062009 AND e.id IS NULL;
